import { shapes, type RawMesh } from '@/src/lib/papercraft-engine';

/** Built-in models, generated by us (no third-party models). Sizes are the longest side in millimetres. */
export interface BuiltInModel {
  id: string;
  name: string;
  description: string;
  defaultSizeMm: number;
  mesh: () => RawMesh;
}

export const BUILT_IN_MODELS: readonly BuiltInModel[] = [
  { id: 'test-cube', name: 'Test cube', description: 'Small cube to try your paper, scoring and glue before a big model.', defaultSizeMm: 40, mesh: () => shapes.cube(100) },
  { id: 'cube', name: 'Cube', description: 'Six squares.', defaultSizeMm: 80, mesh: () => shapes.cube(100) },
  { id: 'tetrahedron', name: 'Tetrahedron', description: 'Four triangles.', defaultSizeMm: 90, mesh: () => shapes.tetrahedron(100) },
  { id: 'octahedron', name: 'Octahedron', description: 'Eight triangles.', defaultSizeMm: 80, mesh: () => shapes.octahedron(100) },
  { id: 'icosahedron', name: 'Icosahedron', description: 'Twenty triangles: a good first low-poly ball.', defaultSizeMm: 90, mesh: () => shapes.icosahedron(100) },
  { id: 'dodecahedron', name: 'Dodecahedron', description: 'Twelve pentagons.', defaultSizeMm: 80, mesh: () => shapes.dodecahedron(100) },
  { id: 'hex-prism', name: 'Hexagon prism', description: 'Two hexagons and six sides.', defaultSizeMm: 90, mesh: () => shapes.prism(6, 50, 100) },
  { id: 'pyramid', name: 'Pyramid', description: 'A five-sided pyramid.', defaultSizeMm: 90, mesh: () => shapes.pyramid(5, 50, 100) },
  { id: 'gem', name: 'Gem', description: 'A low-poly gem with a table and a pointed bottom.', defaultSizeMm: 70, mesh: () => shapes.gem(50) },
  { id: 'l-block', name: 'L-shaped block', description: 'Not convex: shows how inner corners fold the other way.', defaultSizeMm: 90, mesh: () => shapes.lBlock(100) },
];

export function findBuiltInModel(id: string): BuiltInModel | undefined {
  return BUILT_IN_MODELS.find((m) => m.id === id);
}
